Here is the root cause:
The free_pages_prepare() function in mm/page_alloc.c does not clear page->private, allowing stale values to persist on freed pages. When such pages are later allocated as high-order pages and split, tail pages retain stale page->private values, causing a use-after-free in the swap subsystem (swapoff) that assumes page->private is zero for newly allocated pages.

Here is the patch:

 __always_inline bool free_pages_prepare(struct page *page,
 			unsigned int order)
 {
 	int bad = 0;
 	bool skip_kasan_poison = should_skip_kasan_poison(page);
 	bool init = want_init_on_free();
 	bool compound = PageCompound(page);
 	struct folio *folio = page_folio(page);

 	VM_BUG_ON_PAGE(PageTail(page), page);

 	trace_mm_page_free(page, order);
 	kmsan_free_page(page, order);

 	if (memcg_kmem_online() && PageMemcgKmem(page))
 		__memcg_kmem_uncharge_page(page, order);

 	/*
 	 * In rare cases, when truncation or holepunching raced with
 	 * munlock after VM_LOCKED was cleared, Mlocked may still be
 	 * found set here.  This does not indicate a problem, unless
 	 * "unevictable_pgs_cleared" appears worryingly large.
 	 */
 	if (unlikely(folio_test_mlocked(folio))) {
 		long nr_pages = folio_nr_pages(folio);

 		__folio_clear_mlocked(folio);
 		zone_stat_mod_folio(folio, NR_MLOCK, -nr_pages);
 		count_vm_events(UNEVICTABLE_PGCLEARED, nr_pages);
 	}

 	if (unlikely(PageHWPoison(page)) && !order) {
 		/* Do not let hwpoison pages hit pcplists/buddy */
 		reset_page_owner(page, order);
 		page_table_check_free(page, order);
 		pgalloc_tag_sub(page, 1 << order);

 		/*
 		 * The page is isolated and accounted for.
 		 * Mark the codetag as empty to avoid accounting error
 		 * when the page is freed by unpoison_memory().
 		 */
 		clear_page_tag_ref(page);
 		return false;
 	}

 	VM_BUG_ON_PAGE(compound && compound_order(page) != order, page);

 	/*
 	 * Check tail pages before head page information is cleared to
 	 * avoid checking PageCompound for order-0 pages.
 	 */
 	if (unlikely(order)) {
 		int i;

 		if (compound) {
 			page[1].flags.f &= ~PAGE_FLAGS_SECOND;
 #ifdef NR_PAGES_IN_LARGE_FOLIO
 			folio->_nr_pages = 0;
 #endif
 		}
 		for (i = 1; i < (1 << order); i++) {
 			if (compound)
 				bad += free_tail_page_prepare(page, page + i);
 			if (is_check_pages_enabled()) {
 				if (free_page_is_bad(page + i)) {
 					bad++;
 					continue;
 				}
 			}
 			(page + i)->flags.f &= ~PAGE_FLAGS_CHECK_AT_PREP;
 		}
 	}
 	if (folio_test_anon(folio)) {
 		mod_mthp_stat(order, MTHP_STAT_NR_ANON, -1);
 		folio->mapping = NULL;
 	}
 	if (unlikely(page_has_type(page)))
 		/* Reset the page_type (which overlays _mapcount) */
 		page->page_type = UINT_MAX;

 	if (is_check_pages_enabled()) {
 		if (free_page_is_bad(page))
 			bad++;
 		if (bad)
 			return false;
 	}

 	page_cpupid_reset_last(page);
 	page->flags.f &= ~PAGE_FLAGS_CHECK_AT_PREP;
+	page->private = 0;
 	reset_page_owner(page, order);
 	page_table_check_free(page, order);
 	pgalloc_tag_sub(page, 1 << order);

 	if (!PageHighMem(page)) {
 		debug_check_no_locks_freed(page_address(page),
 					   PAGE_SIZE << order);
 		debug_check_no_obj_freed(page_address(page),
 					   PAGE_SIZE << order);
 	}

 	kernel_poison_pages(page, 1 << order);

 	/*
 	 * As memory initialization might be integrated into KASAN,
 	 * KASAN poisoning and memory initialization code must be
 	 * kept together to avoid discrepancies in behavior.
 	 *
 	 * With hardware tag-based KASAN, memory tags must be set before the
 	 * page becomes unavailable via debug_pagealloc or arch_free_page.
 	 */
 	if (!skip_kasan_poison) {
 		kasan_poison_pages(page, order, init);

 		/* Memory is already initialized if KASAN did it internally. */
 		if (kasan_has_integrated_init())
 			init = false;
 	}
 	if (init)
 		kernel_init_pages(page, 1 << order);

 	/*
 	 * arch_free_page() can make the page's contents inaccessible.  s390
 	 * does this.  So nothing which can access the page's contents should
 	 * happen after this.
 	 */
 	arch_free_page(page, order);

 	debug_pagealloc_unmap_pages(page, 1 << order);

 	return true;
 }



